  {target:"Self-actualisation need", c:"maslow", sents:["Kabir is a senior architect at Arcline Designs.","He earns well and is respected by all.","What drives him now is the chance to design a landmark building that uses his full creative potential.","He lives in Chandigarh."], a:2, why:"Achieving full potential: <b>self-actualisation</b>."},
  {target:"Democratic leadership", c:"demo", sents:["Ms. Rao heads the customer service team.","Every Monday, she sits with her team, hears their ideas and decides the week's plan together.","The team has 12 members.","They work in two shifts."], a:1, why:"Decides together with the team: <b>democratic</b>."},
  {target:"Psychological barrier (premature evaluation)", c:"psy", sents:["The manager began explaining the new incentive scheme.","Ankit decided within a minute that it was another trick to cut pay and stopped listening.","The scheme actually raised pay by 8%.","The meeting ended at 5 p.m."], a:1, why:"Judging before hearing it all: <b>premature evaluation</b>."},
  {target:"Financial incentive (co-partnership)", c:"fin", sents:["Ember Tech completed ten years.","To celebrate, it offered its employees company shares at 25% below the market price.","It also held a party.","Its office is in Pune."], a:1, why:"Shares at below-market price: <b>co-partnership / stock option</b>."}
